CREATE OR REPLACE FUNCTION public.game04_apply_formal_present(p_uid uuid, p_item text, p_qty integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.game04_player_state%rowtype; path text[]; target text; size text; r text; v jsonb; current_qty bigint; i integer;
begin
 if p_qty<=0 then raise exception 'INVALID_PRESENT_QUANTITY'; end if;
 -- Caller already holds users row lock; keep same order as commit_state.
 select * into s from public.game04_player_state where user_id=p_uid for update;
 if not found then raise exception 'STATE_NOT_INITIALIZED'; end if;
 v:=s.state;
 if jsonb_typeof(v) is distinct from 'object' then raise exception 'INVALID_INVENTORY_STRUCTURE'; end if;
 if p_item='ENERGY_DRINK' then path:=array['energyDrinks'];
 elsif p_item='SKILL_LB_PART' then path:=array['materials','skill'];
 elsif p_item='EQUIP_LB_PART' then path:=array['materials','equipmentLb'];
 elsif p_item ~ '^(CHAR|EQUIP)_EXP_(S|M|L|XL)$' then
  target:=case when p_item like 'CHAR_%' then 'character' else 'equipment' end;
  size:=case split_part(p_item,'_',3) when 'S' then 'small' when 'M' then 'medium' when 'L' then 'large' when 'XL' then 'xlarge' end;
  path:=array['growthInventory','expItems',target,size];
 elsif p_item ~ '^(SOUL_SELECTOR|GENERIC_SOUL)_(N|R|SR|SSR)$' then
  r:=substring(p_item from '(N|R|SR|SSR)$');
  path:=array['growthInventory',case when p_item like 'SOUL_SELECTOR_%' then 'soulSelectors' else 'genericSouls' end,r];
 else raise exception 'UNSUPPORTED_FORMAL_PRESENT'; end if;
 -- Preserve all existing keys; initialize only absent structure.
 if not(v ? 'growthInventory') then v:=v||jsonb_build_object('growthInventory','{"expItems":{"character":{"small":0,"medium":0,"large":0,"xlarge":0},"equipment":{"small":0,"medium":0,"large":0,"xlarge":0}},"carryExp":{"character":0,"equipment":0},"genericSouls":{"N":0,"R":0,"SR":0,"SSR":0},"soulSelectors":{"N":0,"R":0,"SR":0,"SSR":0}}'::jsonb); end if;
 -- Never overwrite a malformed nonempty inventory or silently grant nothing.
 if array_length(path,1)>1 then
  for i in 1..array_length(path,1)-1 loop
   if jsonb_typeof(v#>path[1:i]) is distinct from 'object' then raise exception 'INVALID_INVENTORY_STRUCTURE'; end if;
  end loop;
 end if;
 if (v#>path) is not null and jsonb_typeof(v#>path) is distinct from 'number' then raise exception 'INVALID_INVENTORY_QUANTITY'; end if;
 current_qty:=coalesce((v#>>path)::bigint,0);
 if current_qty<0 or current_qty+p_qty>9007199254740991 then raise exception 'INVALID_INVENTORY_QUANTITY'; end if;
 v:=jsonb_set(v,path,to_jsonb(current_qty+p_qty),true);
 if (v#>path) is distinct from to_jsonb(current_qty+p_qty) then raise exception 'INVENTORY_GRANT_NOT_APPLIED'; end if;
 update public.game04_player_state set state=v,version=version+1,updated_at=clock_timestamp() where user_id=p_uid;
end $function$

CREATE OR REPLACE FUNCTION public.game04_auth_binding(p_finalize boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_anonymous boolean;
  v_email_confirmed timestamptz;
  v_password boolean;
  v_count integer;
  v_provider text;
  v_method text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  perform pg_advisory_xact_lock(hashtextextended(v_uid::text, 0));
  select u.is_anonymous, u.email_confirmed_at, coalesce(length(u.encrypted_password), 0) > 0
    into v_anonymous, v_email_confirmed, v_password from auth.users u where u.id = v_uid;
  if not found then raise exception 'AUTH_REQUIRED'; end if;
  if not exists(select 1 from public.users where id = v_uid)
    or not exists(select 1 from public.game04_player_state where user_id = v_uid)
    then raise exception 'PLAYER_NOT_FOUND'; end if;
  select count(*), min(provider) into v_count, v_provider from auth.identities where user_id = v_uid;
  select auth_method into v_method from public.user_account_auth_methods where user_id = v_uid for update;
  if v_anonymous then
    if p_finalize then raise exception 'VERIFIED_IDENTITY_REQUIRED'; end if;
    return jsonb_build_object('userId', v_uid, 'linked', false, 'method', null, 'needsPassword', false);
  end if;
  if v_count <> 1 or v_provider not in ('email', 'google') then raise exception 'SINGLE_IDENTITY_REQUIRED'; end if;
  if v_method is not null and v_method <> upper(v_provider) then raise exception 'IDENTITY_CONFLICT'; end if;
  if v_provider = 'email' and (v_email_confirmed is null or not v_password) then
    if p_finalize then raise exception 'EMAIL_CONFIRMATION_AND_PASSWORD_REQUIRED'; end if;
    return jsonb_build_object('userId', v_uid, 'linked', false, 'method', 'EMAIL', 'needsPassword', v_email_confirmed is not null);
  end if;
  if p_finalize then
    insert into public.user_account_auth_methods(user_id, auth_method) values(v_uid, upper(v_provider))
      on conflict(user_id) do nothing;
    select auth_method into v_method from public.user_account_auth_methods where user_id = v_uid for update;
    if v_method <> upper(v_provider) then raise exception 'IDENTITY_CONFLICT'; end if;
  end if;
  return jsonb_build_object('userId', v_uid, 'linked', v_method is not null, 'method', upper(v_provider), 'needsPassword', false);
end; $function$

CREATE OR REPLACE FUNCTION public.game04_billing_grant_order(p_order_id uuid, p_session_id text, p_amount_jpy integer, p_currency text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare item public.billing_orders; result jsonb;
begin
 select * into item from public.billing_orders where id=p_order_id for update;
 if not found then raise exception 'ORDER_NOT_FOUND';end if;
 if item.billing_mode is distinct from 'sandbox' then raise exception 'TEST_MODE_REQUIRED';end if;
 if item.product_id='game04_vip_30d' and (item.amount_jpy<>480 or item.product_snapshot->'items' is distinct from '[]'::jsonb) then
  raise exception 'VIP_PRODUCT_CONTRACT_REQUIRED';
 end if;
 -- Existing grant records payment, ordinary assets, lots and purchase count once.
 result:=public.billing_grant_order(p_order_id,p_session_id,p_amount_jpy,p_currency);
 if item.product_snapshot->>'game04InventoryVersion'='APPROVED_GROWTH_V1_20260921' then
  update public.presents p set source_kind='GAME04_PAID_FORMAL',source_metadata=jsonb_build_object('game04PaidVersion','APPROVED_GROWTH_V1_20260921','funding','paid','orderId',item.id::text)
  from public.billing_asset_lots l where l.order_id=item.id and l.present_id=p.id and p.status='UNCLAIMED'
   and public.game04_paid_item_path(p.item_id) is not null;
 end if;
 if item.product_id='game04_vip_30d' then
  -- Same transaction: entitlement failure rolls back order GRANTED/payment ledger too.
  perform public.game04_grant_vip(item.user_id,item.id::text);
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.game04_billing_reserve_order(p_user_id uuid, p_request_id uuid, p_product_id text, p_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare existing public.billing_orders; reserved jsonb;
begin
 if p_mode is distinct from 'sandbox' then raise exception 'TEST_MODE_REQUIRED'; end if;
 if p_product_id is null or p_product_id not in ('beginner_pack_01','ticket_pack_01','growth_pack_01','awakening_pack_01',
 'diamond_300','diamond_500','diamond_1000','diamond_3000','diamond_5000','diamond_10000','game04_vip_30d') then raise exception 'INVALID_PRODUCT';end if;
 perform 1 from public.users where id=p_user_id for update;
 if not found then raise exception 'USER_NOT_FOUND';end if;
 select * into existing from public.billing_orders where user_id=p_user_id and request_id=p_request_id;
 if existing.id is not null then
  -- Existing request keeps the original immutable snapshot and delegate conflict checks.
  return public.billing_reserve_order(p_user_id,p_request_id,p_product_id,p_mode);
 end if;
 if p_product_id='game04_vip_30d' then
  if exists(select 1 from public.game04_vip_entitlements where user_id=p_user_id and expires_at>statement_timestamp()) then
   raise exception 'VIP_ALREADY_ACTIVE';
  end if;
  if exists(select 1 from public.billing_orders o where o.user_id=p_user_id and o.product_id=p_product_id and
   (o.status='PENDING' or (o.status='GRANTED' and not exists(select 1 from public.game04_vip_grants g where g.order_id=o.id::text)))) then
   raise exception 'VIP_ORDER_PENDING';
  end if;
 end if;
 reserved:=public.billing_reserve_order(p_user_id,p_request_id,p_product_id,p_mode);
 update public.billing_orders set product_snapshot=product_snapshot||jsonb_build_object('game04InventoryVersion','APPROVED_GROWTH_V1_20260921') where id=(reserved->>'id')::uuid;
 select to_jsonb(o) into reserved from public.billing_orders o where o.id=(reserved->>'id')::uuid;
 return reserved;
end $function$

CREATE OR REPLACE FUNCTION public.game04_capture_asset_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare body jsonb:=to_jsonb(new); kind text; master_id text; event_id text;
begin
 kind:=case tg_table_name when 'user_characters' then 'character' when 'user_skills' then 'skill' else 'equipment' end;
 master_id:=case kind when 'character' then body->>'character_id' when 'skill' then body->>'skill_card_id' else body->>'equipment_id' end;
 event_id:='asset:'||kind||':'||(body->>'id');
 insert into public.game04_acquisition_events(id,user_id,payload) values(event_id,(body->>'user_id')::uuid,jsonb_build_object('id',event_id,'kind',kind,'masterId',master_id,'legacyId',body->>'id','instanceId',body->>'id')) on conflict(id) do nothing;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.game04_capture_gacha_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare results jsonb; item jsonb; idx integer:=0; kind text; event_id text; master_id text;
begin
 if tg_table_name='gacha_execution_history' then
  if new.status<>'COMPLETED' then return new; end if;
  if tg_op='UPDATE' and old.status='COMPLETED' then return new; end if;
  results:=new.result_payload->'results';
 else results:=jsonb_build_array(new.result_payload); end if;
 for item in select value from jsonb_array_elements(coalesce(results,'[]'::jsonb)) loop
  idx:=idx+1; kind:=lower(item->>'type');
  if kind not in ('character','skill') or item->>'outcome'='new' then continue; end if;
  master_id:=coalesce(item->>'character_id',item->>'item_id');
  if master_id is null then raise exception 'GAME04_ACQUISITION_RESULT_MISSING_ID'; end if;
  event_id:='receipt:'||tg_table_name||':'||new.user_id||':'||new.request_id||':'||idx;
  insert into public.game04_acquisition_events(id,user_id,payload) values(event_id,new.user_id,jsonb_build_object('id',event_id,'kind',kind,'masterId',master_id)) on conflict(id) do nothing;
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.game04_capture_login_delivery()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare st jsonb; r jsonb; login_day date;
begin
 if tg_op='UPDATE' then
  if new.total_logins is not distinct from old.total_logins then return new; end if;
 end if;
 select state into st from public.game04_player_state where user_id=new.user_id;
 r:=st->'loginBonusReceipt';
 login_day:=(new.last_claimed_at at time zone 'Asia/Tokyo')::date;
 -- The formal producer updates state before progress, in the same transaction.
 -- Legacy progress changes and restored/stale receipts must not become formal delivery facts.
 if st->>'loginBonusVersion' is distinct from 'game04-login-30-v1-20260921'
  or r->>'masterVersion' is distinct from 'game04-login-30-v1-20260921'
  or r->>'claimed' is distinct from 'true' or r->>'delivery' is distinct from 'DIRECT'
  or r->>'total_logins' is distinct from new.total_logins::text
  or r->>'day_number' is distinct from new.current_day::text
  or st->>'loginBonusLastDate' is distinct from login_day::text
  or r->>'last_claimed_date' is distinct from login_day::text
  or login_day is distinct from (statement_timestamp() at time zone 'Asia/Tokyo')::date
 then return new; end if;
 insert into public.game04_login_deliveries(user_id,login_date,total_logins,day_number,delivered_at,master_version)
 values(new.user_id,login_day,new.total_logins,new.current_day,new.last_claimed_at,'game04-login-30-v1-20260921')
 on conflict do nothing;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.game04_capture_named_asset_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare delta integer; kind text; manifest jsonb; i integer; event_id text;
begin
 delta:=new.quantity-case when tg_op='INSERT' then 0 else old.quantity end;
 if delta<=0 then return new; end if;
 select data into manifest from public.game04_redesign_master where key='release_manifest';
 if exists(select 1 from jsonb_array_elements(coalesce(manifest->'characters','[]'::jsonb)) m where m->>'id'=new.item_id) then kind:='character';
 elsif exists(select 1 from jsonb_array_elements(coalesce(manifest->'skills','[]'::jsonb)) m where m->>'id'=new.item_id) then kind:='skill';
 else return new; end if;
 for i in 1..delta loop
  event_id:='item_asset:'||gen_random_uuid();
  insert into public.game04_acquisition_events(id,user_id,payload) values(event_id,new.user_id,jsonb_build_object('id',event_id,'kind',kind,'masterId',new.item_id));
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.game04_capture_territory_clear()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare snap jsonb; owner uuid; wins integer; amount bigint; inserted integer;
begin
 if old.state->>'status'<>'active' or new.state->>'status'<>'defeated' then return new; end if;
 snap:=old.state->'territorySnapshot';
 if snap#>>'{raidMaster,type}' is distinct from 'unlock' then return new; end if;
 if (new.state->>'level')::integer<>(snap#>>'{raidMaster,maxLevel}')::integer or (new.state->>'hp')::bigint<>0 or (old.state->>'expiresAt')::timestamptz<=clock_timestamp() then return new; end if;
 owner:=(old.state->>'ownerId')::uuid;
 -- Result already includes the triggering battle win. Later settled battles cannot change this receipt.
 select coalesce((p->>'wins')::integer,0) into wins from jsonb_array_elements(new.state->'participants') p where p->>'userId'=owner::text;
 wins:=coalesce(wins,0); amount:=case when wins>=3 then (snap#>>'{destination,clearExp}')::bigint else 0 end;
 insert into public.game04_territory_clear_receipts(room_id,user_id,eligible,experience,owner_wins,master_version) values(new.id,owner,wins>=3,amount,wins,snap->>'masterVersion') on conflict(room_id) do nothing;
 get diagnostics inserted=row_count;
 if inserted=1 and amount>0 then
  -- Only the independent progress row is touched: never owner users/state locks from another player's settlement.
  update public.game04_territory_progress set experience=experience+amount,updated_at=now() where user_id=owner;
  if not found then raise exception 'TERRITORY_OWNER_PROGRESS_MISSING'; end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.game04_capture_territory_unlock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
 -- A stale application snapshot cannot clear the durable once-only receipt.
 if TG_OP='UPDATE' and old.state ? 'territoryUnlockGrantedVersion' then
  new.state:=jsonb_set(new.state,'{territoryUnlockGrantedVersion}',old.state->'territoryUnlockGrantedVersion');
 elsif coalesce(new.state->'clearedStages','[]'::jsonb) @> '["mino-5"]'::jsonb then
  -- Preserve the whole existing inventory and add exactly one invasion order.
  new.state:=jsonb_set(new.state,'{materials}',coalesce(new.state->'materials','{}'::jsonb)||jsonb_build_object('unlock',coalesce((new.state#>>'{materials,unlock}')::integer,0)+1));
  new.state:=jsonb_set(new.state,'{territoryUnlockGrantedVersion}','"GAME04_TERRITORY_HOST_PROVISIONAL_20260923"'::jsonb);
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.game04_commit_gacha(p_user_id uuid, p_expected_version bigint, p_state jsonb, p_cash_delta bigint, p_before_diamonds integer, p_diamond_cost integer, p_request_id uuid, p_operation text, p_request_payload jsonb, p_receipt jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
 u public.users%rowtype;
 prior jsonb;
 v_result jsonb;
 v_saved_state jsonb;
 v_ticket_id text;
 v_ticket_cost integer:=0;
 v_ticket_balance integer;
 v_receipt jsonb;
 v_jst_day text;
begin
 if p_request_id is null or p_operation not in ('normal_gacha','special_gacha','special_gacha_exchange','formal_gacha','formal_gacha_exchange')
  or jsonb_typeof(p_request_payload) is distinct from 'object' or jsonb_typeof(p_state) is distinct from 'object'
  or jsonb_typeof(p_receipt) is distinct from 'object' then raise exception 'INVALID_GACHA_REQUEST'; end if;
 select * into u from public.users where id=p_user_id for update;
 if not found then raise exception 'GAME_USER_NOT_FOUND'; end if;
 select r.result into prior from public.game04_requests r where r.user_id=p_user_id and r.request_id=p_request_id;
 if found then
  if prior->>'operation' is distinct from p_operation or prior->'requestPayload' is distinct from p_request_payload then raise exception 'REQUEST_ID_REUSED'; end if;
  return prior;
 end if;
 select s.state into v_saved_state from public.game04_player_state s where s.user_id=p_user_id for update;
 if not found then raise exception 'GAME_STATE_NOT_FOUND'; end if;
 -- questTicketGrants is the monotonic G2 delivery ledger. A gacha request may
 -- neither decrement it nor persist the server-only balance projection.
 if coalesce(p_state->'questTicketGrants','{}'::jsonb) is distinct from coalesce(v_saved_state->'questTicketGrants','{}'::jsonb)
  or p_state ? 'gachaTicketBalances' then raise exception 'INVALID_GACHA_TICKET_STATE'; end if;
 if p_operation='special_gacha' and p_request_payload->>'payment'='TICKET' then
  if p_request_payload->>'count' is distinct from '1' then raise exception 'INVALID_GACHA_TICKET_COUNT'; end if;
  v_ticket_id:=case p_request_payload->>'category'
   when 'character' then 'SPECIAL_TICKET_CHARACTER'
   when 'skill' then 'SPECIAL_TICKET_SKILL'
   when 'equipment' then 'SPECIAL_TICKET_EQUIPMENT'
   else null end;
  if v_ticket_id is null then raise exception 'INVALID_GACHA_TICKET_CATEGORY'; end if;
  v_ticket_cost:=1;
 elsif p_request_payload->>'payment'='TICKET' then
  raise exception 'INVALID_GACHA_TICKET_OPERATION';
 end if;
 if p_operation='normal_gacha' then
  v_jst_day:=to_char(clock_timestamp() at time zone 'Asia/Tokyo','YYYY-MM-DD');
  if p_receipt->>'normalGachaJstDay' is distinct from v_jst_day
   or (p_request_payload->>'payment'='FREE' and p_state->>'dailyNormalGachaDate' is distinct from v_jst_day) then
   raise exception 'GACHA_DAY_CHANGED' using errcode='40001';
  end if;
 end if;
 if p_diamond_cost is null or p_diamond_cost<0 or p_diamond_cost>3000
  or p_before_diamonds is null or (p_state->>'diamonds')::integer is distinct from p_before_diamonds-p_diamond_cost then raise exception 'INVALID_GACHA_COST'; end if;
 -- Existing expiry trigger remains the balance authority. Re-read after it runs.
 update public.users set neon_diamonds=neon_diamonds where id=p_user_id returning * into u;
 if u.neon_diamonds<>p_before_diamonds then raise exception 'STATE_CONFLICT' using errcode='40001'; end if;
 if u.neon_diamonds<p_diamond_cost then raise exception 'INSUFFICIENT_RESOURCE'; end if;
 update public.users set neon_diamonds=neon_diamonds-p_diamond_cost where id=p_user_id;
 if v_ticket_id is not null then
  select i.quantity into v_ticket_balance from public.user_items i
   where i.user_id=p_user_id and i.item_id=v_ticket_id for update;
  if coalesce(v_ticket_balance,0)<v_ticket_cost then raise exception 'INSUFFICIENT_RESOURCE'; end if;
  -- Keep the ordinary quantity update so the existing paid-lot expiry/spend
  -- trigger remains the authority for expiring and consuming paid ticket lots.
  update public.user_items set quantity=quantity-v_ticket_cost,updated_at=clock_timestamp()
   where user_id=p_user_id and item_id=v_ticket_id returning quantity into v_ticket_balance;
 end if;
 v_receipt:=p_receipt||case when v_ticket_id is null then '{}'::jsonb else jsonb_build_object(
  'specialGachaTicketId',v_ticket_id,
  'specialGachaTicketCost',v_ticket_cost,
  'specialGachaTicketBalanceAfter',v_ticket_balance
 ) end;
 v_result:=public.game04_commit_growth_state(p_user_id,p_expected_version,p_state,p_cash_delta,0,p_request_id,p_receipt=>v_receipt);
 v_result:=v_result||jsonb_build_object('operation',p_operation,'requestPayload',p_request_payload,'receipt',v_receipt);
 update public.game04_requests set result=v_result where user_id=p_user_id and request_id=p_request_id;
 return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.game04_commit_growth_state(p_user_id uuid, p_expected_version bigint, p_state jsonb, p_cash_delta bigint, p_energy_delta integer, p_request_id uuid, p_battle jsonb DEFAULT NULL::jsonb, p_raid jsonb DEFAULT NULL::jsonb, p_raid_expected_version bigint DEFAULT NULL::bigint, p_receipt jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare u public.users%rowtype; prior jsonb; before_progress jsonb; next_progress jsonb; v_result jsonb;
 current_exp integer; current_level integer; next_exp integer; next_level integer; expected_exp integer; expected_level integer;
 gain integer; energy_delta integer:=p_energy_delta; energy_limit integer; saved_input jsonb;
begin
 select * into u from public.users where id=p_user_id for update;
 if not found then raise exception 'GAME_USER_NOT_FOUND'; end if;
 select r.result into prior from public.game04_requests r where r.user_id=p_user_id and r.request_id=p_request_id;
 if found then return prior; end if;
 before_progress:=public.game04_get_growth_state(p_user_id)->'playerProgress';
 -- get_state can apply natural recovery; use the actual locked balance for refill, never stack refill deltas.
 select * into u from public.users where id=p_user_id;
 next_progress:=p_state->'playerProgress';
 if next_progress->>'status'='active' then
  if before_progress->>'status' is distinct from 'active' or next_progress->>'version' is distinct from 'APPROVED_GROWTH_V1_20260921' then raise exception 'PLAYER_GROWTH_MIGRATION_REQUIRED'; end if;
  current_exp:=(before_progress->>'exp')::integer; current_level:=(before_progress->>'level')::integer;
  next_exp:=(next_progress->>'exp')::integer; next_level:=(next_progress->>'level')::integer;
  if next_exp is null or next_level is null or next_exp<current_exp or next_level<current_level or next_level>100 then raise exception 'PLAYER_GROWTH_INVALID'; end if;
  if next_exp<>current_exp or next_level<>current_level then
   if p_battle->>'status' is distinct from 'settled' or p_battle#>>'{result,battle,outcome}' is distinct from 'win' then raise exception 'PLAYER_EXP_QUEST_ONLY'; end if;
   select b.input into saved_input from public.game04_battles b where b.id=(p_battle->>'id')::uuid and b.user_id=p_user_id and b.status='started' and (
    b.kind='quest'
    or (b.kind='raid'
      and b.input->>'raidMasterVersion'='GAME04_RAID_FORMAL_20260923'
      and b.input#>>'{playerExpReward,status}'='APPROVED'
      and exists (
        select 1 from public.game04_raid_rooms r
        where r.id::text=b.target_id
          and r.state#>>'{raidSnapshot,type}'='encounter'
          and r.state#>>'{raidSnapshot,masterVersion}'=b.input->>'raidMasterVersion'
          and b.input#>>'{playerExpReward,version}'=b.input->>'raidMasterVersion'
          and r.state#>>'{raidSnapshot,playerExp}'=b.input#>>'{playerExpReward,amount}'
      )
    )
   );
   if saved_input is null or saved_input->'playerExpReward' is null then raise exception 'PLAYER_EXP_SNAPSHOT_REQUIRED'; end if;
   gain:=(saved_input#>>'{playerExpReward,amount}')::integer;
   if gain is null or gain<0 then raise exception 'PLAYER_EXP_INVALID'; end if;
   expected_exp:=case when current_level>=100 then current_exp else least(public.game04_growth_cumulative_exp(100),current_exp::bigint+gain)::integer end;
   select max(l) into expected_level from generate_series(current_level,100) l where public.game04_growth_cumulative_exp(l)<=expected_exp;
   if next_exp<>expected_exp or next_level<>expected_level then raise exception 'PLAYER_GROWTH_INVALID'; end if;
   if next_level>current_level then
    select (data->>'energyMax')::integer into energy_limit from public.game04_redesign_master where key='runtime';
    energy_delta:=greatest(0,energy_limit-u.vitality);
    p_battle:=jsonb_set(p_battle,'{result,playerGrowth,energyRecovered}',to_jsonb(energy_delta));
    p_battle:=jsonb_set(p_battle,'{result,playerGrowth,energy}',to_jsonb(u.vitality+energy_delta));
   end if;
  end if;
 end if;
 v_result:=public.game04_commit_state(p_user_id,p_expected_version,p_state,p_cash_delta,energy_delta,p_request_id,p_battle,p_raid,p_raid_expected_version);
 if next_progress->>'status'='active' then
  update public.users set level=next_level,xp=next_exp-public.game04_growth_cumulative_exp(next_level) where id=p_user_id;
 end if;
 v_result:=v_result||jsonb_build_object('state',public.game04_get_growth_state(p_user_id),'receipt',coalesce(p_receipt,'{}'::jsonb));
 if p_battle->>'status'='settled' then v_result:=v_result||jsonb_build_object('battleResult',p_battle->'result'); end if;
 update public.game04_requests set result=v_result where user_id=p_user_id and request_id=p_request_id;
 return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.game04_commit_shop_exchange(p_user_id uuid, p_expected_version bigint, p_state jsonb, p_before_diamonds integer, p_diamond_cost integer, p_cash_delta bigint, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare u public.users%rowtype; prior jsonb; old_state jsonb; old_version bigint; result jsonb;
 paid_total bigint; remaining_paid bigint; take_qty bigint; segment jsonb; paid_segments jsonb:='[]';
 lot public.billing_asset_lots; item text; reward_qty bigint; energy_delta bigint; unlock_delta bigint;
 cumulative bigint:=0; previous_alloc bigint:=0; allocated bigint; pid uuid; source_kind text;
begin
 select * into u from public.users where id=p_user_id for update;
 if not found then raise exception 'GAME_USER_NOT_FOUND';end if;
 select r.result into prior from public.game04_requests r where r.user_id=p_user_id and r.request_id=p_request_id;
 if found then return prior;end if;
 if p_diamond_cost is null or p_diamond_cost<0 or p_diamond_cost>5000
 or p_before_diamonds is null or (p_state->>'diamonds')::integer is distinct from p_before_diamonds-p_diamond_cost then
  raise exception 'INVALID_EXCHANGE_COST';end if;
 update public.users set neon_diamonds=neon_diamonds where id=p_user_id returning * into u;
 if u.neon_diamonds<>p_before_diamonds then raise exception 'STATE_CONFLICT' using errcode='40001';end if;
 if u.neon_diamonds<p_diamond_cost then raise exception 'INSUFFICIENT_RESOURCE';end if;
 select state,version into old_state,old_version from public.game04_player_state where user_id=p_user_id for update;
 if not found then raise exception 'STATE_NOT_INITIALIZED';end if;
 if old_version is distinct from p_expected_version then raise exception 'STATE_CONFLICT' using errcode='40001';end if;
 if p_diamond_cost>0 then
  energy_delta:=coalesce((p_state->>'energyDrinks')::bigint,0)-coalesce((old_state->>'energyDrinks')::bigint,0);
  unlock_delta:=coalesce((p_state#>>'{materials,unlock}')::bigint,0)-coalesce((old_state#>>'{materials,unlock}')::bigint,0);
  if energy_delta between 1 and 10 and unlock_delta=0 and p_cash_delta=0 and p_diamond_cost=50*energy_delta then
   item:='ENERGY_DRINK';reward_qty:=energy_delta;source_kind:='GAME04_PAID_FORMAL';
  elsif unlock_delta=1 and energy_delta=0 and p_cash_delta=0 and p_diamond_cost=100 then
   item:='RAID_UNLOCK_TICKET';reward_qty:=1;source_kind:='GAME04_PAID_FORMAL';
  elsif energy_delta=0 and unlock_delta=0 and p_diamond_cost in (300,500,1000,3000,5000) and p_cash_delta=p_diamond_cost::bigint*10 then
   item:='CASH';reward_qty:=p_cash_delta;source_kind:='GAME04_PAID_DERIVED';
  else raise exception 'INVALID_EXCHANGE_REWARD';end if;
  select coalesce(sum(remaining_quantity),0) into paid_total from public.billing_asset_lots
   where user_id=p_user_id and item_id='DIAMOND' and claimed_at is not null and remaining_quantity>0 and expires_at>statement_timestamp();
  -- Match billing_apply_lot_delta: free first, then earliest paid expiry.
  remaining_paid:=greatest(0,p_diamond_cost-greatest(0,u.neon_diamonds-paid_total));
  for lot in select * from public.billing_asset_lots where user_id=p_user_id and item_id='DIAMOND'
   and claimed_at is not null and remaining_quantity>0 and expires_at>statement_timestamp() order by expires_at,id for update loop
   exit when remaining_paid=0;take_qty:=least(remaining_paid,lot.remaining_quantity);
   paid_segments:=paid_segments||jsonb_build_array(jsonb_build_object('id',lot.id,'order',lot.order_id,'quantity',take_qty,'issued',lot.issued_at,'expiry',lot.expires_at));
   remaining_paid:=remaining_paid-take_qty;
  end loop;
  if remaining_paid<>0 then raise exception 'PAID_LOT_SOURCE_MISMATCH';end if;
 end if;
 update public.users set neon_diamonds=neon_diamonds-p_diamond_cost where id=p_user_id;
 -- Existing state/receipt transaction and CAS guard; failures also roll back DIA expiry/debit.
 result:=public.game04_commit_growth_state(p_user_id,p_expected_version,p_state,p_cash_delta,0,p_request_id,
  p_receipt=>jsonb_build_object('gameplayMeasurement',jsonb_build_object('contractVersion','game04-gameplay-v1','action','shop_exchange','stateVersionBefore',p_expected_version,'stateVersionAfter',p_expected_version+1,'diamondCost',p_diamond_cost)));
 -- Inventory has already been granted above. These CLAIMED presents are provenance only.
 -- New lots are inserted after state commit, so that grant cannot consume its own newly issued lot.
 for segment in select value from jsonb_array_elements(paid_segments) loop
  cumulative:=cumulative+(segment->>'quantity')::bigint;
  allocated:=ceil(reward_qty::numeric*cumulative/p_diamond_cost)::bigint-previous_alloc;
  previous_alloc:=previous_alloc+allocated;
  if allocated>0 then
   insert into public.presents(user_id,item_id,quantity,message,status,expire_at,claimed_at,source_kind,source_metadata)
   values(p_user_id,item,allocated,'輝石交換','CLAIMED',(segment->>'expiry')::timestamptz,clock_timestamp(),source_kind,
    jsonb_build_object('game04PaidVersion','APPROVED_GROWTH_V1_20260921','funding','paid','orderId',segment->>'order','sourceLotId',segment->>'id','exchangeRequestId',p_request_id)) returning id into pid;
   insert into public.billing_asset_lots(order_id,user_id,present_id,item_id,issued_quantity,remaining_quantity,issued_at,expires_at,source_lot_id,claimed_at)
   values((segment->>'order')::uuid,p_user_id,pid,item,allocated,allocated,(segment->>'issued')::timestamptz,(segment->>'expiry')::timestamptz,(segment->>'id')::uuid,clock_timestamp());
  end if;
 end loop;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.game04_commit_state(p_user_id uuid, p_expected_version bigint, p_state jsonb, p_cash_delta bigint, p_energy_delta integer, p_request_id uuid, p_battle jsonb DEFAULT NULL::jsonb, p_raid jsonb DEFAULT NULL::jsonb, p_raid_expected_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s public.game04_player_state%rowtype; u public.users%rowtype; prior jsonb; battle_row public.game04_battles%rowtype; room public.game04_raid_rooms%rowtype; out_state jsonb; room_out jsonb; battle_id uuid;
begin
 select * into u from public.users where id=p_user_id for update;
 if not found then raise exception 'GAME_USER_NOT_FOUND'; end if;
 select result into prior from public.game04_requests where user_id=p_user_id and request_id=p_request_id;
 if found then return prior; end if;
 select * into s from public.game04_player_state where user_id=p_user_id for update;
 if not found then raise exception 'STATE_NOT_INITIALIZED'; end if;
 if s.version<>p_expected_version then raise exception 'STATE_CONFLICT' using errcode='40001'; end if;
 if u.cash+p_cash_delta<0 or u.vitality+p_energy_delta<0 then raise exception 'INSUFFICIENT_RESOURCE'; end if;
 if p_battle is not null then
  battle_id := (p_battle->>'id')::uuid;
  select * into battle_row from public.game04_battles where id=battle_id for update;
  if p_battle->>'status'='started' then
   if found then raise exception 'BATTLE_ALREADY_STARTED'; end if;
   insert into public.game04_battles(id,user_id,kind,target_id,seed,input,status) values(battle_id,p_user_id,p_battle->>'kind',p_battle->>'targetId',(p_battle->>'seed')::bigint,p_battle->'input','started');
  elsif p_battle->>'status'='settled' then
   if not found or battle_row.user_id<>p_user_id then raise exception 'BATTLE_NOT_FOUND'; end if;
   if battle_row.status='settled' then raise exception 'BATTLE_ALREADY_SETTLED'; end if;
   update public.game04_battles set status='settled',result=p_battle->'result',settled_at=now() where id=battle_id;
  else raise exception 'INVALID_BATTLE_STATUS'; end if;
 end if;
 if p_raid is not null then
  select * into room from public.game04_raid_rooms where id=(p_raid->>'id')::uuid for update;
  if found then
   if p_raid_expected_version is null or room.version<>p_raid_expected_version then raise exception 'RAID_CONFLICT' using errcode='40001'; end if;
   update public.game04_raid_rooms set state=p_raid,version=version+1,updated_at=now() where id=room.id returning state||jsonb_build_object('version',version) into room_out;
   if coalesce((p_raid->>'rescueCount')::integer,0)>coalesce((room.state->>'rescueCount')::integer,0)
      or (p_raid->>'rescueWindowStartedAt' is distinct from room.state->>'rescueWindowStartedAt' and coalesce((p_raid->>'rescueCount')::integer,0)>0) then
    insert into public.game04_social_events(room_id,author_id,kind,body) values(room.id,p_user_id,'raid_rescue',jsonb_build_object('roomId',room.id,'masterId',p_raid->>'masterId','level',p_raid->'level','channels',jsonb_build_array('global','activity')));
   end if;
  else
   if coalesce(p_raid_expected_version,-1)<>-1 then raise exception 'RAID_CONFLICT' using errcode='40001'; end if;
   insert into public.game04_raid_rooms(id,state) values((p_raid->>'id')::uuid,p_raid) returning state||jsonb_build_object('version',version) into room_out;
  end if;
 end if;
 update public.users set cash=cash+p_cash_delta,vitality=vitality+p_energy_delta,updated_at=now() where id=p_user_id;
 update public.game04_player_state set version=version+1,state=p_state-'vipExpiresAt'-'cash'-'diamonds'-'energy'-'version',updated_at=now() where user_id=p_user_id;
 out_state:=jsonb_build_object('state',public.game04_get_state(p_user_id),'room',room_out);
 insert into public.game04_requests(user_id,request_id,result) values(p_user_id,p_request_id,out_state);
 return out_state;
end $function$

CREATE OR REPLACE FUNCTION public.game04_deliver_due_vip()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare item public.game04_vip_deliveries%rowtype; delivered integer:=0;
begin
 -- Unclaimed days are still delivered after expiry when a worker recovers from downtime.
 for item in select * from public.game04_vip_deliveries
  where delivered_at is null and due_at<=statement_timestamp()
  order by due_at,order_id,ordinal for update skip locked limit 1000 loop
  update public.users set neon_diamonds=neon_diamonds+item.amount where id=item.user_id;
  if not found then raise exception 'GAME_USER_NOT_FOUND';end if;
  update public.game04_vip_deliveries set delivered_at=statement_timestamp() where order_id=item.order_id and ordinal=item.ordinal;
  delivered:=delivered+1;
 end loop;
 return delivered;
end $function$

CREATE OR REPLACE FUNCTION public.game04_deliver_quest_tickets()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare ticket text; before_amount bigint; after_amount bigint;
begin
 for ticket in select jsonb_object_keys(coalesce(new.state->'questTicketGrants','{}'::jsonb) || coalesce(old.state->'questTicketGrants','{}'::jsonb)) loop
  if ticket not in ('SPECIAL_TICKET_CHARACTER','SPECIAL_TICKET_SKILL','SPECIAL_TICKET_EQUIPMENT') then raise exception 'INVALID_QUEST_TICKET'; end if;
  if coalesce(new.state#>>array['questTicketGrants',ticket],'0') !~ '^[0-9]+$' then raise exception 'INVALID_QUEST_TICKET_AMOUNT'; end if;
  before_amount:=coalesce((old.state#>>array['questTicketGrants',ticket])::bigint,0);
  after_amount:=coalesce((new.state#>>array['questTicketGrants',ticket])::bigint,0);
  if after_amount<before_amount or after_amount>2147483647 then raise exception 'INVALID_QUEST_TICKET_AMOUNT'; end if;
  if after_amount>before_amount then
   insert into public.user_items(user_id,item_id,quantity) values(new.user_id,ticket,(after_amount-before_amount)::integer)
   on conflict(user_id,item_id) do update set quantity=user_items.quantity+excluded.quantity,updated_at=now();
  end if;
 end loop;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.game04_formal_paid_balance_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item text; path text[]; before_qty bigint; after_qty bigint; expired bigint; paid bigint; spend bigint; take_qty bigint; lot public.billing_asset_lots;
begin
 for item in select distinct l.item_id from public.billing_asset_lots l
 join public.presents p on p.id=l.present_id
 where l.user_id=new.user_id and l.claimed_at is not null and l.remaining_quantity>0
 and p.source_kind='GAME04_PAID_FORMAL' loop
  path:=public.game04_paid_item_path(item);
  if path is null then raise exception 'UNSUPPORTED_PAID_FORMAL_ITEM'; end if;
  if jsonb_typeof(old.state#>path) is distinct from 'number' or jsonb_typeof(new.state#>path) is distinct from 'number' then raise exception 'INVALID_PAID_FORMAL_INVENTORY';end if;
  before_qty:=(old.state#>>path)::bigint; after_qty:=(new.state#>>path)::bigint;
  if before_qty<0 or after_qty<0 then raise exception 'INVALID_PAID_FORMAL_INVENTORY';end if;
  expired:=0;paid:=0;spend:=greatest(before_qty-after_qty,0);
  for lot in select l.* from public.billing_asset_lots l join public.presents p on p.id=l.present_id
   where l.user_id=new.user_id and l.item_id=item and l.claimed_at is not null and l.remaining_quantity>0 and p.source_kind='GAME04_PAID_FORMAL'
   order by l.expires_at,l.id for update of l loop
   if lot.expires_at<=statement_timestamp() then
    expired:=expired+lot.remaining_quantity;
    update public.billing_asset_lots set expired_quantity=expired_quantity+remaining_quantity,remaining_quantity=0 where id=lot.id;
   else paid:=paid+lot.remaining_quantity;end if;
  end loop;
  if before_qty-expired<spend then raise exception 'EXPIRED_ASSET_BALANCE';end if;
  -- Preserve the existing paid-item consumption policy: earliest paid expiry first.
  for lot in select l.* from public.billing_asset_lots l join public.presents p on p.id=l.present_id
   where l.user_id=new.user_id and l.item_id=item and l.claimed_at is not null and l.remaining_quantity>0 and p.source_kind='GAME04_PAID_FORMAL'
   order by l.expires_at,l.id for update of l loop
   exit when spend=0;take_qty:=least(spend,lot.remaining_quantity);
   update public.billing_asset_lots set remaining_quantity=remaining_quantity-take_qty where id=lot.id;spend:=spend-take_qty;
  end loop;
  new.state:=jsonb_set(new.state,path,to_jsonb(after_qty-expired));
 end loop;
 if new.state is distinct from old.state and new.version=old.version then new.version:=old.version+1;new.updated_at:=clock_timestamp();end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.game04_get_growth_state(p_user_id uuid, p_initial jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare result jsonb; progress jsonb; u public.users%rowtype;
begin
 result:=public.game04_get_state(p_user_id,p_initial);
 if result is null then return null; end if;
 select * into u from public.users where id=p_user_id;
 progress:=result->'playerProgress';
 if progress->>'version'='APPROVED_GROWTH_V1_20260921' and progress->>'status'='active'
  and (progress->>'level')::integer=u.level
  and (progress->>'exp')::integer-public.game04_growth_cumulative_exp(u.level)=u.xp then
  return result;
 end if;
 if progress is null and u.level=1 and u.xp=0 then
  progress:=jsonb_build_object('version','APPROVED_GROWTH_V1_20260921','status','active','level',1,'exp',0);
 else
  progress:=jsonb_build_object('version',coalesce(progress->>'version','LEGACY_UNMIGRATED'),'status','migration_pending','level',u.level,'exp',u.xp);
 end if;
 return result||jsonb_build_object('playerProgress',progress);
end $function$

CREATE OR REPLACE FUNCTION public.game04_get_session_state(p_user_id uuid, p_initial jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare st jsonb; claim jsonb;
begin
 st:=public.game04_get_growth_state(p_user_id,p_initial);
 if st is null then return null;end if;
 claim:=public.game04_process_login_bonus(p_user_id);
 if coalesce((claim->>'claimed')::boolean,false) then
  st:=public.game04_get_growth_state(p_user_id);
 end if;
 return st;
end $function$

CREATE OR REPLACE FUNCTION public.game04_get_state(p_user_id uuid, p_initial jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare u public.users%rowtype; s public.game04_player_state%rowtype; cfg jsonb; recovered integer; recovery_seconds integer; energy_max integer; vip timestamptz;
begin
 select * into u from public.users where id=p_user_id for update;
 if not found then raise exception 'GAME_USER_NOT_FOUND'; end if;
 update public.users set neon_diamonds=neon_diamonds,cash=cash where id=p_user_id returning * into u;
 select data into cfg from public.game04_redesign_master where key='runtime';
 energy_max := (cfg->>'energyMax')::integer; recovery_seconds := (cfg->>'energyRecoverySeconds')::integer;
 recovered := greatest(0,floor(extract(epoch from (now()-coalesce(u.vitality_last_recovered_at,now())))/recovery_seconds)::integer);
 if u.vitality < energy_max and recovered>0 then
  update public.users set vitality=least(energy_max,vitality+recovered),vitality_last_recovered_at=case when vitality+recovered>=energy_max then now() else coalesce(vitality_last_recovered_at,now())+make_interval(secs=>recovered*recovery_seconds) end where id=p_user_id returning * into u;
 elsif u.vitality>=energy_max then
  update public.users set vitality_last_recovered_at=now() where id=p_user_id returning * into u;
 end if;
 if p_initial is not null then insert into public.game04_player_state(user_id,state) values(p_user_id,p_initial) on conflict(user_id) do nothing; end if;
 -- Only expired claimed formal lots require a state write; ordinary reads remain read-only here.
 if exists(select 1 from public.billing_asset_lots l join public.presents p on p.id=l.present_id
  where l.user_id=p_user_id and l.claimed_at is not null and l.remaining_quantity>0 and l.expires_at<=statement_timestamp() and p.source_kind='GAME04_PAID_FORMAL') then
  update public.game04_player_state set state=state where user_id=p_user_id;
 end if;
 select * into s from public.game04_player_state where user_id=p_user_id;
 if not found then return null; end if;
 select expires_at into vip from public.game04_vip_entitlements where user_id=p_user_id;
 return s.state || jsonb_build_object('userId',p_user_id,'version',s.version,'cash',u.cash,'diamonds',u.neon_diamonds,'energy',u.vitality,'energyMax',energy_max,'vipExpiresAt',vip);
end $function$

CREATE OR REPLACE FUNCTION public.game04_grant_vip(p_user_id uuid, p_order_id text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare paid public.billing_orders%rowtype; expiry timestamptz; started timestamptz; row_count integer;
begin
 select * into paid from public.billing_orders where id::text=p_order_id and user_id=p_user_id for update;
 if not found or paid.product_id<>'game04_vip_30d' or paid.status<>'GRANTED' or paid.amount_jpy<>480 or paid.granted_at is null then raise exception 'VERIFIED_VIP_PAYMENT_REQUIRED';end if;
 perform 1 from public.users where id=p_user_id for update;
 if not found then raise exception 'GAME_USER_NOT_FOUND';end if;
 if exists(select 1 from public.game04_vip_grants where order_id=p_order_id and user_id<>p_user_id) then raise exception 'ORDER_USER_MISMATCH';end if;
 if exists(select 1 from public.game04_vip_grants where order_id=p_order_id) then
  return paid.granted_at+interval '720 hours';
 end if;
 started:=paid.granted_at;
 select expires_at into expiry from public.game04_vip_entitlements where user_id=p_user_id;
 if expiry>started then raise exception 'VIP_ALREADY_ACTIVE';end if;
 expiry:=started+interval '720 hours';
 insert into public.game04_vip_grants(order_id,user_id,days,created_at) values(p_order_id,p_user_id,30,started);
 insert into public.game04_vip_entitlements(user_id,expires_at) values(p_user_id,expiry)
 on conflict(user_id) do update set expires_at=excluded.expires_at;
 insert into public.game04_vip_deliveries(order_id,user_id,ordinal,due_at)
 select p_order_id,p_user_id,n+1,started+make_interval(hours=>24*n) from generate_series(0,29)n;
 -- Purchase-time grant is in the same transaction as entitlement, never deferred to login.
 update public.users set neon_diamonds=neon_diamonds+100 where id=p_user_id;
 update public.game04_vip_deliveries set delivered_at=statement_timestamp() where order_id=p_order_id and ordinal=1;
 return expiry;
end $function$

CREATE OR REPLACE FUNCTION public.game04_host_formal_territory(p_user_id uuid, p_request_id uuid, p_destination_id text, p_raid_master jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cfg jsonb; d jsonb; boss jsonb; s public.game04_player_state%rowtype; prior jsonb; context jsonb; slots integer; available integer; rid uuid:=gen_random_uuid(); room jsonb; result jsonb; user_name text;
begin
 if p_request_id is null then raise exception 'REQUEST_ID_REQUIRED'; end if;
 -- Same user mutex and state lock order as game04_commit_state.
 select username into user_name from public.users where id=p_user_id for update;
 if not found then raise exception 'GAME_USER_NOT_FOUND'; end if;
 select q.result into prior from public.game04_requests q where q.user_id=p_user_id and q.request_id=p_request_id;
 if found then
  if prior->>'operation' is distinct from 'host_territory' or prior->>'destinationId' is distinct from p_destination_id then raise exception 'REQUEST_ID_REUSED'; end if;
  return prior;
 end if;
 select * into s from public.game04_player_state where user_id=p_user_id for update;
 if not found then raise exception 'STATE_NOT_INITIALIZED'; end if;
 context:=public.game04_territory_context(p_user_id);cfg:=context->'master';
 -- Hosting never locks existing rooms; clear-trigger order room -> progress cannot cycle.
 perform 1 from public.game04_territory_progress where user_id=p_user_id for update;
 context:=public.game04_territory_context(p_user_id);cfg:=context->'master';
 select value into d from jsonb_array_elements(cfg->'destinations') where value->>'id'=p_destination_id;
 if d is null then raise exception 'TERRITORY_DESTINATION_NOT_FOUND'; end if;
 if coalesce((context#>>'{progress,unlocked}')::boolean,false) is not true then raise exception 'TERRITORY_FEATURE_LOCKED'; end if;
 if d ? 'unavailableReason' then raise exception 'TERRITORY_HOSTING_POLICY_UNCONFIRMED'; end if;
 if (context#>>'{progress,level}')::integer<(d->>'requiredLevel')::integer then raise exception 'TERRITORY_LEVEL_REQUIRED'; end if;
 select (value->>'hostingSlots')::integer into slots from jsonb_array_elements(cfg->'levels') where (value->>'level')::integer=(context#>>'{progress,level}')::integer;
 if (context->>'activeHostingCount')::integer>=slots then raise exception 'TERRITORY_HOSTING_SLOTS_FULL'; end if;
 available:=coalesce((context->'items'->>(d->>'itemId'))::integer,0);
 if available<(d->>'itemCount')::integer then raise exception 'TERRITORY_ITEM_REQUIRED'; end if;
 select value||jsonb_build_object('durationMinutes',d->'durationMinutes') into boss from jsonb_array_elements(cfg->'raidMasters') where value->>'id'=d->>'raidMasterId';
 if p_raid_master is not null then
  if p_raid_master->>'id' is distinct from boss->>'id' or p_raid_master->>'masterVersion' is distinct from boss->>'masterVersion' or jsonb_array_length(p_raid_master->'stages')<>12 then raise exception 'TERRITORY_FORMAL_MASTER_MISMATCH'; end if;
  boss:=p_raid_master||jsonb_build_object('durationMinutes',d->'durationMinutes');
 end if;
 if d->>'itemId'='raid_unlock' then s.state:=jsonb_set(s.state,'{materials,unlock}',to_jsonb(available-(d->>'itemCount')::integer));
 else s.state:=jsonb_set(s.state,'{territoryItems}',coalesce(s.state->'territoryItems','{}'::jsonb)||jsonb_build_object(d->>'itemId',available-(d->>'itemCount')::integer)); end if;
 room:=jsonb_build_object('id',rid,'masterId',boss->>'id','ownerId',p_user_id,'level',1,'hp',boss->'sharedHp','maxHp',boss->'sharedHp',
 'createdAt',clock_timestamp(),'expiresAt',clock_timestamp()+make_interval(mins=>(d->>'durationMinutes')::integer),'status','active','rescueCount',0,'rescueWindowStartedAt',clock_timestamp(),
 'participants',jsonb_build_array(jsonb_build_object('userId',p_user_id,'name',coalesce(user_name,'主催者'),'wins',0,'attempts',0,'totalDamage',0,'joinedLevel',1)),
 'settledBattleIds','[]'::jsonb,'rewardGrants','[]'::jsonb,
 'territorySnapshot',jsonb_build_object('masterVersion',cfg->>'version','status',cfg->>'status','destination',d,'raidMaster',boss,'battleRules',cfg->'battleRules'));
 insert into public.game04_raid_rooms(id,state) values(rid,room);
 update public.game04_player_state set state=s.state,version=version+1,updated_at=now() where user_id=p_user_id;
 result:=jsonb_build_object('operation','host_territory','destinationId',p_destination_id,'state',public.game04_get_state(p_user_id),'room',room||jsonb_build_object('version',0),'territory',public.game04_territory_context(p_user_id));
 insert into public.game04_requests(user_id,request_id,result) values(p_user_id,p_request_id,result);
 return result;
end $function$

