CREATE OR REPLACE FUNCTION public.game04_observe_state_restore(p_user_id uuid, p_request_id uuid, p_observed_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare prior bigint; current_version bigint;
begin
 if p_request_id is null or p_observed_version is null or p_observed_version<0 then raise exception 'INVALID_OBSERVATION'; end if;
 select observed_version into prior from public.game04_state_restore_observations where user_id=p_user_id and request_id=p_request_id;
 if found then
  if prior<>p_observed_version then raise exception 'REQUEST_ID_REUSED'; end if;
  return jsonb_build_object('recorded',true,'observedVersion',prior);
 end if;
 select version into current_version from public.game04_player_state where user_id=p_user_id;
 if current_version is distinct from p_observed_version then return jsonb_build_object('recorded',false,'reason','version_changed'); end if;
 insert into public.game04_state_restore_observations(user_id,request_id,observed_version)
 values(p_user_id,p_request_id,p_observed_version) on conflict do nothing;
 select observed_version into prior from public.game04_state_restore_observations where user_id=p_user_id and request_id=p_request_id;
 if prior is distinct from p_observed_version then raise exception 'REQUEST_ID_REUSED'; end if;
 return jsonb_build_object('recorded',true,'observedVersion',p_observed_version);
end $function$

CREATE OR REPLACE FUNCTION public.game04_process_login_bonus(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare u public.users%rowtype; s public.game04_player_state%rowtype; progress public.user_login_bonuses%rowtype;
 today date:=(statement_timestamp() at time zone 'Asia/Tokyo')::date; step integer; total integer;
 st jsonb; rewards jsonb; receipt jsonb; row jsonb; gems integer:=0; amount integer; path text[];
begin
 select * into u from public.users where id=p_user_id for update;
 if not found then raise exception 'GAME_USER_NOT_FOUND';end if;
 select * into s from public.game04_player_state where user_id=p_user_id for update;
 if not found then return jsonb_build_object('claimed',false,'reason','STATE_NOT_READY');end if;
 select * into progress from public.user_login_bonuses where user_id=p_user_id for update;
 if found and (progress.last_claimed_at at time zone 'Asia/Tokyo')::date=today then
  return jsonb_build_object('claimed',false,'already_claimed',true,'current_step',progress.current_day,'total_logins',progress.total_logins,'last_claimed_date',today,'delivery','DIRECT','masterVersion',case when s.state->>'loginBonusLastDate'=today::text then s.state->>'loginBonusVersion' else null end);
 end if;
 step:=case when progress.user_id is null then 1 else progress.current_day%30+1 end;
 total:=coalesce(progress.total_logins,0)+1;
 st:=s.state||jsonb_build_object('loginBonusVersion','game04-login-30-v1-20260921','loginBonusLastDate',today);
 st:=jsonb_set(st,'{souls}',coalesce(st->'souls','{}'::jsonb));
 st:=jsonb_set(st,'{souls,char_reiji_01}',to_jsonb(coalesce((st#>>'{souls,char_reiji_01}')::integer,0)+2));
 rewards:=jsonb_build_array(jsonb_build_object('kind','soul','id','char_reiji_01','amount',2),jsonb_build_object('kind','cash','amount',10000));
 if step in (3,8,13,18,23,28) then
  st:=jsonb_set(st,'{growthInventory}',coalesce(st->'growthInventory','{"expItems":{"character":{"small":0,"medium":0,"large":0,"xlarge":0},"equipment":{"small":0,"medium":0,"large":0,"xlarge":0}},"carryExp":{"character":0,"equipment":0},"genericSouls":{"N":0,"R":0,"SR":0,"SSR":0},"soulSelectors":{"N":0,"R":0,"SR":0,"SSR":0}}'::jsonb));
  st:=jsonb_set(st,'{growthInventory,expItems}',coalesce(st#>'{growthInventory,expItems}','{}'::jsonb));
  st:=jsonb_set(st,'{growthInventory,expItems,character}',coalesce(st#>'{growthInventory,expItems,character}','{"small":0,"medium":0,"large":0,"xlarge":0}'::jsonb));
  st:=jsonb_set(st,'{growthInventory,expItems,equipment}',coalesce(st#>'{growthInventory,expItems,equipment}','{"small":0,"medium":0,"large":0,"xlarge":0}'::jsonb));
  st:=jsonb_set(st,'{growthInventory,expItems,character,large}',to_jsonb(coalesce((st#>>'{growthInventory,expItems,character,large}')::integer,0)+1));
  st:=jsonb_set(st,'{growthInventory,expItems,equipment,large}',to_jsonb(coalesce((st#>>'{growthInventory,expItems,equipment,large}')::integer,0)+2));
  rewards:=rewards||jsonb_build_array(jsonb_build_object('kind','character_exp_item','id','large','amount',1),jsonb_build_object('kind','equipment_exp_item','id','large','amount',2));
 end if;
 if step in (5,20,10,25,15,30) then
  path:=array['questTicketGrants',case when step in (5,20) then 'SPECIAL_TICKET_CHARACTER' when step in (10,25) then 'SPECIAL_TICKET_SKILL' else 'SPECIAL_TICKET_EQUIPMENT' end];
  amount:=case when step in (10,25) then 2 else 1 end;
  st:=jsonb_set(st,'{questTicketGrants}',coalesce(st->'questTicketGrants','{}'::jsonb));
  st:=jsonb_set(st,path,to_jsonb(coalesce((st#>>path)::integer,0)+amount));
  rewards:=rewards||jsonb_build_array(jsonb_build_object('kind','ticket','id',path[2],'amount',amount));
 end if;
 if step in (7,14,21) then gems:=100;end if;
 receipt:=jsonb_build_object('claimed',true,'already_claimed',false,'current_step',step,'day_number',step,'total_logins',total,'last_claimed_date',today,'delivery','DIRECT','rewards',rewards,'freeDiamonds',gems,'masterVersion','game04-login-30-v1-20260921');
 st:=jsonb_set(st,'{loginBonusReceipt}',receipt);
 update public.users set cash=cash+10000,neon_diamonds=neon_diamonds+gems where id=p_user_id;
 -- Ticket delta trigger delivers to the existing ticket inventory in the same transaction.
 update public.game04_player_state set state=st,version=version+1,updated_at=statement_timestamp() where user_id=p_user_id;
 insert into public.user_login_bonuses(user_id,current_day,total_logins,last_claimed_at)
 values(p_user_id,step,total,statement_timestamp()) on conflict(user_id) do update
 set current_day=excluded.current_day,total_logins=excluded.total_logins,last_claimed_at=excluded.last_claimed_at;
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.game04_territory_context(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cfg jsonb; xp bigint; current_level integer; active_count integer; stored jsonb; inventory jsonb; is_unlocked boolean;
begin
 select data into cfg from public.game04_redesign_master where key='territory';
 perform public.game04_validate_territory_master(cfg);
 insert into public.game04_territory_progress(user_id,experience) values(p_user_id,(cfg->>'initialExp')::bigint) on conflict(user_id) do nothing;
 select experience into xp from public.game04_territory_progress where user_id=p_user_id;
 select (l->>'level')::integer into current_level from jsonb_array_elements(cfg->'levels') l where (l->>'requiredExp')::bigint<=xp order by (l->>'level')::integer desc limit 1;
 select count(*) into active_count from public.game04_raid_rooms where state->>'ownerId'=p_user_id::text and state->>'status'='active' and (state->>'expiresAt')::timestamptz>clock_timestamp() and (state#>>'{territorySnapshot,raidMaster,type}'='unlock' or (not state ? 'territorySnapshot' and state->>'masterId'='unlock_shadow'));
 select state into stored from public.game04_player_state where user_id=p_user_id;
 is_unlocked:=coalesce(stored->'clearedStages','[]'::jsonb) @> jsonb_build_array(coalesce(cfg->>'unlockStageId','mino-5'));
 inventory:=coalesce(stored->'territoryItems','{}'::jsonb)||jsonb_build_object('raid_unlock',coalesce((stored#>>'{materials,unlock}')::integer,0));
 return jsonb_build_object('master',cfg,'progress',jsonb_build_object('experience',xp,'level',current_level,'unlocked',is_unlocked),'activeHostingCount',active_count,'items',inventory);
end $function$

CREATE OR REPLACE FUNCTION public.game04_validate_territory_master(cfg jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare l jsonb; d jsonb; r jsonb; prev_exp bigint:=-1; prev_level integer:=0; prev_slots integer:=0; cap integer;
begin
 if cfg is null or not cfg ?& array['version','status','levelCap','initialExp','legacyMigrationExp','levels','destinations','raidMasters','battleRules'] or nullif(cfg->>'version','') is null or coalesce(cfg->>'status','') not in ('PREVIEW_PROVISIONAL','APPROVED') then raise exception 'TERRITORY_MASTER_INVALID'; end if;
 if exists(select 1 from unnest(array['levelCap','initialExp','legacyMigrationExp']) k where jsonb_typeof(cfg->k) is distinct from 'number') then raise exception 'TERRITORY_LEVEL_MASTER_INVALID'; end if;
 if jsonb_typeof(cfg->'battleRules') is distinct from 'object' or exists(select 1 from unnest(array['defenseFactor','advantageMultiplier','disadvantageMultiplier','spRecoveryDivisor','burstLukDivisor','enemySpRecoveryDivisor','maxPlayerActions','initialSpRatio']) k where jsonb_typeof(cfg->'battleRules'->k) is distinct from 'number') then raise exception 'TERRITORY_BATTLE_RULES_INVALID'; end if;
 cap:=(cfg->>'levelCap')::integer;
 if cap<1 or (cfg->>'initialExp')::bigint<0 or (cfg->>'legacyMigrationExp')::bigint<0 or jsonb_typeof(cfg->'levels') is distinct from 'array' or jsonb_array_length(cfg->'levels')<>cap then raise exception 'TERRITORY_LEVEL_MASTER_INVALID'; end if;
 for l in select value from jsonb_array_elements(cfg->'levels') loop
  if exists(select 1 from unnest(array['level','requiredExp','hostingSlots']) k where jsonb_typeof(l->k) is distinct from 'number') then raise exception 'TERRITORY_LEVEL_MASTER_INVALID'; end if;
  if not l ?& array['level','requiredExp','hostingSlots'] or (l->>'level')::integer<>prev_level+1 or (l->>'requiredExp')::bigint<=prev_exp or (l->>'hostingSlots')::integer<1 or (l->>'hostingSlots')::integer<prev_slots then raise exception 'TERRITORY_LEVEL_MASTER_INVALID'; end if;
  if prev_level=0 and (l->>'requiredExp')::bigint<>0 then raise exception 'TERRITORY_LEVEL_MASTER_INVALID'; end if;
  prev_slots:=(l->>'hostingSlots')::integer;prev_level:=(l->>'level')::integer;prev_exp:=(l->>'requiredExp')::bigint;
 end loop;
 if jsonb_typeof(cfg->'destinations') is distinct from 'array' or jsonb_array_length(cfg->'destinations')<1 or jsonb_typeof(cfg->'raidMasters') is distinct from 'array' then raise exception 'TERRITORY_DESTINATION_MASTER_INVALID'; end if;
 if (select count(*)<>count(distinct value->>'id') from jsonb_array_elements(cfg->'destinations')) or (select count(*)<>count(distinct value->>'id') from jsonb_array_elements(cfg->'raidMasters')) then raise exception 'TERRITORY_DUPLICATE_MASTER_ID'; end if;
 for d in select value from jsonb_array_elements(cfg->'destinations') loop
  if exists(select 1 from unnest(array['requiredLevel','itemCount','durationMinutes','clearExp']) k where jsonb_typeof(d->k) is distinct from 'number') or exists(select 1 from unnest(array['id','itemId','raidMasterId']) k where jsonb_typeof(d->k) is distinct from 'string') then raise exception 'TERRITORY_DESTINATION_MASTER_INVALID'; end if;
  if not d ?& array['id','itemId','requiredLevel','itemCount','durationMinutes','clearExp','raidMasterId'] or nullif(d->>'id','') is null or nullif(d->>'itemId','') is null or (d->>'requiredLevel')::integer<1 or (d->>'requiredLevel')::integer>cap or (d->>'itemCount')::integer<1 or (d->>'durationMinutes')::integer<1 or (d->>'clearExp')::bigint<0 then raise exception 'TERRITORY_DESTINATION_MASTER_INVALID'; end if;
  select value into r from jsonb_array_elements(cfg->'raidMasters') where value->>'id'=d->>'raidMasterId';
  if exists(select 1 from unnest(array['sharedHp','maxLevel','maxParticipants','enemyGrowthPerLevel','sharedHpGrowthPerLevel']) k where jsonb_typeof(r->k) is distinct from 'number') then raise exception 'TERRITORY_RAID_MASTER_INVALID'; end if;
  if r is null or not r ?& array['id','type','sharedHp','maxLevel','maxParticipants','enemy','appearanceImages','enemyGrowthPerLevel','sharedHpGrowthPerLevel'] or r->>'type'<>'unlock' or (r->>'sharedHp')::bigint<1 or (r->>'maxLevel')::integer<1 or (r->>'maxParticipants')::integer<1 or r->'enemy' is null then raise exception 'TERRITORY_RAID_MASTER_INVALID'; end if;
 end loop;
end $function$
